def give_every_type_one_look(apps, schema_editor):  # noqa: ARG001
    """Each existing room type gets one unnamed look holding all its rooms and photos, so
    guests see exactly what they saw before until a host adds a second look."""
    unit_model = apps.get_model("stay", "Unit")
    look_model = apps.get_model("stay", "RoomLook")
    room_model = apps.get_model("stay", "Room")
    media_model = apps.get_model("stay", "UnitMedia")
